scwin.checkVal = function () {
    let dataInfo = $p.data.getInfo();
    dataInfo = dataInfo.mf_dataMap1.dataMapInfo.id;
    dataInfo = dataInfo.indexOf('??');

    return dataInfo === -1;
};

scwin.unitTest = function () {
    //Unit 
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wfm_exam1_btn_exec1_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};

scwin.unitTest();
